package com.library.service; import com.library.dao.UserDAO; import com.library.enums.Role; import com.library.exception.AuthenticationException; import com.library.model.User; import com.library.security.PasswordUtil; import com.library.session.SessionManager; import com.library.util.ValidationUtil;
public class AuthService { private final UserDAO users=new UserDAO(); public User loginAdmin(String email,String password){ValidationUtil.email(email);return authenticate(users.findByEmail(email.trim()).orElseThrow(()->new AuthenticationException("Invalid administrator ID or password.")),Role.ADMIN,password);} public User loginStudent(String enrollmentNo,String password){long enrollment=parseEnrollment(enrollmentNo);return authenticate(users.findByMemberId(enrollment).orElseThrow(()->new AuthenticationException("Invalid enrollment number or password.")),Role.MEMBER,password);} public void changeAdminPassword(String adminId,String current,String replacement){User user=SessionManager.getCurrentUser();ValidationUtil.email(adminId);if(user==null||user.getRole()!=Role.ADMIN)throw new AuthenticationException("Administrator access required.");if(!user.getEmail().equalsIgnoreCase(adminId.trim()))throw new AuthenticationException("Enter the currently signed-in admin ID.");if(!PasswordUtil.matches(current,user.getPasswordHash()))throw new AuthenticationException("Current password is incorrect.");ValidationUtil.password(replacement);String hash=PasswordUtil.hash(replacement);users.updatePassword(user.getUserId(),hash);user.setPasswordHash(hash);} private long parseEnrollment(String value){try{long enrollment=Long.parseLong(ValidationUtil.required(value,"Enrollment number"));ValidationUtil.enrollment(enrollment);return enrollment;}catch(NumberFormatException e){throw new AuthenticationException("Enter a valid 11-digit enrollment number.");}} private User authenticate(User user,Role expectedRole,String password){if(password==null||password.isEmpty())throw new AuthenticationException("Password is required.");if(user.getRole()!=expectedRole)throw new AuthenticationException("Use the correct login option for this account.");if(!"ACTIVE".equals(user.getStatus()))throw new AuthenticationException("This account is inactive. Please contact the library administrator.");if(!PasswordUtil.matches(password,user.getPasswordHash()))throw new AuthenticationException("Invalid credentials.");SessionManager.login(user);return user;} }
